"""
Schemas for Phase 7 Fuzzy Evidence Reasoning module.
"""

from dataclasses import dataclass
from typing import Optional, Dict


@dataclass
class FuzzyInput:
    """Inputs to the fuzzy reasoning engine.
    Values should be in [0, 1].
    """
    relevance: float
    attribution_shap: float
    attribution_lime: float
    intervention_influence: float
    
    # Placeholders for future phases
    contradiction_degree: float = 0.0
    source_reliability: float = 0.75  # Wikipedia default
    stability_score: float = 1.0


@dataclass
class FuzzyOutput:
    """Outputs generated by the fuzzy reasoning engine."""
    evidence_relevance: float
    evidence_reliability: float
    support_degree: float
    contradiction_degree: float
    explanation_confidence: float


@dataclass
class BaselineOutput:
    """Output for the simple weighted aggregation baseline."""
    baseline_score: float
    adjusted_baseline_score: float
